def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0])
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    # Only isolated endpoints in the background lanes are extended to
    # complete strokes: line between separate colored runs on each axis.
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg]
    out=[row[:] for row in grid]
    for r in range(h):
        cs=[c for rr,c in pts if rr==r]
        for a,b in zip(cs,cs[1:]):
            for c in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    for c in range(w):
        rs=[r for r,cc in pts if cc==c]
        for a,b in zip(rs,rs[1:]):
            for r in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    return out
